@@ -0,0 +1,266 @@
+'use client';
+
+// ══════════════════════════════════════════════════════════════
+// components/settings/GradePromotionCard.tsx
+// 학년 변경(진급 이벤트) UI — #208.
+//
+// 프로필의 다른 항목과 달리 즉시 저장하지 않는다. 학년 변경은 내신 등급제·수능
+// D-day 기준 학년도·교육과정·계획 캐시를 한꺼번에 움직이는 이벤트라,
+// "무엇이 바뀌는지"를 먼저 보여주고 확인을 받는다.
+//
+// 특히 등급제가 바뀌는 전환에서는 기존 성적을 환산하지 않는다는 사실을 명시한다 —
+// 학생이 "내 3등급이 9등급제 3등급으로 바뀌나?"를 걱정하지 않도록.
+// ══════════════════════════════════════════════════════════════
+import { useCallback, useEffect, useState } from 'react';
+import {
+  STUDENT_TYPES,
+  classifyTransition,
+  gradeSystemChange,
+  transitionRequiresReason,
+  describeTransition,
+  type TransitionKind,
+} from '@/lib/promotion';
+import { gradeContext, type StudentType } from '@/lib/grade-system';
+
+interface TransitionRow {
+  id: string;
+  from_type: StudentType;
+  to_type: StudentType;
+  kind: TransitionKind;
+  reason: string | null;
+  created_at: string;
+  description?: string;
+}
+
+interface PromotionResponse {
+  to_type: StudentType;
+  description: string;
+  grade_system_change: { changed: boolean; notice: string | null };
+  stamped_grade_rows: number;
+  daily_plan_stale: boolean;
+}
+
+export default function GradePromotionCard({ studentType }: { studentType: StudentType }) {
+  const [current, setCurrent] = useState<StudentType>(studentType);
+  const [target, setTarget] = useState<StudentType | ''>('');
+  const [reason, setReason] = useState('');
+  const [confirming, setConfirming] = useState(false);
+  const [saving, setSaving] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const [result, setResult] = useState<PromotionResponse | null>(null);
+  const [history, setHistory] = useState<TransitionRow[]>([]);
+
+  const loadHistory = useCallback(async () => {
+    try {
+      const res = await fetch('/api/students/promotion');
+      if (!res.ok) return;
+      const data = await res.json();
+      setHistory((data.transitions ?? []) as TransitionRow[]);
+    } catch {
+      // 이력은 부가 정보 — 실패해도 변경 기능 자체는 쓸 수 있어야 한다.
+    }
+  }, []);
+
+  useEffect(() => {
+    void loadHistory();
+  }, [loadHistory]);
+
+  const kind = target ? classifyTransition(current, target) : null;
+  const systemChange = target ? gradeSystemChange(current, target) : null;
+  const needsReason = kind ? transitionRequiresReason(kind) : false;
+  const currentCtx = gradeContext(current);
+
+  async function submit() {
+    if (!target) return;
+    setSaving(true);
+    setError(null);
+    try {
+      const res = await fetch('/api/students/promotion', {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ to_type: target, reason: reason.trim() || undefined }),
+      });
+      const data = await res.json();
+      if (!res.ok) {
+        setError(data.error ?? '학년 변경에 실패했어요.');
+        return;
+      }
+      setResult(data as PromotionResponse);
+      setCurrent(target);
+      setTarget('');
+      setReason('');
+      setConfirming(false);
+      void loadHistory();
+    } catch {
+      setError('네트워크 오류로 학년을 변경하지 못했어요.');
+    } finally {
+      setSaving(false);
+    }
+  }
+
+  const card = 'rounded-2xl border border-slate-200 bg-white p-5';
+  const inputCls = 'w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-700';
+
+  return (
+    <div className={card}>
+      <h2 className="text-sm font-bold text-slate-700">학년</h2>
+      <p className="mt-1 text-xs text-slate-500">
+        현재 <span className="font-semibold text-slate-700">{currentCtx.fullLabel}</span>
+      </p>
+      <p className="mt-2 text-xs text-slate-500">
+        진급·재수 전환처럼 학년이 실제로 바뀌었을 때만 변경하세요. 학습계획·수능 D-day·
+        내신 등급제가 함께 바뀝니다.
+      </p>
+
+      {/* 변경 결과 */}
+      {result && (
+        <div className="mt-4 rounded-xl border border-emerald-200 bg-emerald-50 p-3">
+          <p className="text-sm font-bold text-emerald-800">{result.description} 완료</p>
+          <ul className="mt-1.5 space-y-0.5 text-xs text-emerald-700">
+            {result.grade_system_change.notice && <li>{result.grade_system_change.notice}</li>}
+            {result.stamped_grade_rows > 0 && (
+              <li>
+                기존 성적 {result.stamped_grade_rows}건에 입력 당시 등급제를 기록해 두었어요 —
+                환산 없이 원래 등급 그대로 표시됩니다.
+              </li>
+            )}
+            <li>
+              학습계획은 다음 생성부터 새 학년 기준으로 반영돼요.{' '}
+              <a href="/roadmap" className="font-semibold underline">로드맵에서 다시 생성 →</a>
+            </li>
+            {result.daily_plan_stale && (
+              <li>
+                오늘 계획은 이전 학년 기준으로 이미 만들어져 있어요. 오늘 것부터 바꾸려면
+                직접 다시 생성해 주세요.
+              </li>
+            )}
+          </ul>
+        </div>
+      )}
+
+      {error && (
+        <div role="alert" className="mt-4 rounded-xl border border-red-200 bg-red-50 p-3 text-sm font-semibold text-red-700">
+          {error}
+        </div>
+      )}
+
+      {/* 변경 폼 */}
+      <div className="mt-4">
+        <label htmlFor="promotion-target" className="block text-xs font-semibold text-slate-500">
+          바꿀 학년
+        </label>
+        <select
+          id="promotion-target"
+          value={target}
+          onChange={(e) => {
+            setTarget(e.target.value as StudentType | '');
+            setConfirming(false);
+            setResult(null);
+          }}
+          className={`${inputCls} mt-1`}
+        >
+          <option value="">선택 안 함</option>
+          {STUDENT_TYPES.filter((t) => t !== current).map((t) => (
+            <option key={t} value={t}>{gradeContext(t).gradeLabel}</option>
+          ))}
+        </select>
+      </div>
+
+      {/* 무엇이 바뀌는지 — 확인 전에 반드시 보여준다 */}
+      {target && kind && systemChange && (
+        <div className="mt-3 rounded-xl border border-amber-200 bg-amber-50 p-3">
+          <p className="text-sm font-bold text-amber-900">
+            {describeTransition(current, target, kind)}
+          </p>
+          <ul className="mt-1.5 space-y-0.5 text-xs text-amber-800">
+            <li>{gradeContext(target).fullLabel} 기준으로 바뀝니다.</li>
+            {systemChange.notice ? (
+              <li>{systemChange.notice}</li>
+            ) : (
+              <li>내신 등급제는 그대로 {gradeContext(target).gradeSystemLabel}입니다.</li>
+            )}
+            <li>
+              {gradeContext(target).showSuneungDday
+                ? '수능 D-day가 새 학년도 기준으로 다시 계산됩니다.'
+                : '수능 D-day 대신 학기 흐름 기준으로 표시됩니다.'}
+            </li>
+            <li>학습계획은 다음 생성부터 새 학년 기준으로 만들어집니다.</li>
+          </ul>
+
+          {needsReason && (
+            <div className="mt-3">
+              <label htmlFor="promotion-reason" className="block text-xs font-semibold text-amber-900">
+                변경 사유 (필수)
+              </label>
+              <input
+                id="promotion-reason"
+                type="text"
+                value={reason}
+                onChange={(e) => setReason(e.target.value)}
+                placeholder="예: 온보딩에서 학년을 잘못 선택했어요"
+                maxLength={300}
+                className={`${inputCls} mt-1`}
+              />
+              <p className="mt-1 text-[11px] text-amber-800">
+                진급·재수가 아닌 학년 정정은 사유를 남겨야 나중에 되돌릴 근거가 됩니다.
+              </p>
+            </div>
+          )}
+
+          <div className="mt-3 flex gap-2">
+            {confirming ? (
+              <>
+                <button
+                  type="button"
+                  onClick={() => void submit()}
+                  disabled={saving || (needsReason && !reason.trim())}
+                  className="rounded-lg bg-amber-700 px-3 py-2 text-xs font-bold text-white disabled:opacity-50"
+                >
+                  {saving ? '변경 중…' : '정말 바꿀게요'}
+                </button>
+                <button
+                  type="button"
+                  onClick={() => setConfirming(false)}
+                  disabled={saving}
+                  className="rounded-lg border border-amber-300 px-3 py-2 text-xs font-semibold text-amber-900"
+                >
+                  취소
+                </button>
+              </>
+            ) : (
+              <button
+                type="button"
+                onClick={() => setConfirming(true)}
+                disabled={needsReason && !reason.trim()}
+                className="rounded-lg bg-amber-700 px-3 py-2 text-xs font-bold text-white disabled:opacity-50"
+              >
+                학년 변경
+              </button>
+            )}
+          </div>
+        </div>
+      )}
+
+      {/* 이력 — 되돌릴 근거. 되돌리기는 위 셀렉트에서 이전 학년을 고르면 된다. */}
+      {history.length > 0 && (
+        <div className="mt-4 border-t border-slate-200 pt-3">
+          <h3 className="text-xs font-bold text-slate-600">학년 변경 이력</h3>
+          <ul className="mt-1.5 space-y-1">
+            {history.map((h) => (
+              <li key={h.id} className="flex flex-wrap items-baseline gap-x-2 text-[11px] text-slate-600">
+                <span className="font-semibold text-slate-800">
+                  {h.description ?? describeTransition(h.from_type, h.to_type, h.kind)}
+                </span>
+                <span className="tabular-nums text-slate-500">{h.created_at.slice(0, 10)}</span>
+                {h.reason && <span className="text-slate-500">— {h.reason}</span>}
+              </li>
+            ))}
+          </ul>
+          <p className="mt-2 text-[11px] text-slate-500">
+            잘못 바꿨다면 위에서 이전 학년을 다시 선택하면 되돌릴 수 있어요.
+          </p>
+        </div>
+      )}
+    </div>
+  );
+}
