+// ══════════════════════════════════════════════════════════════
+// lib/grade-provenance.ts
+// 성적 행의 "등급제 출처" — 기록 당시의 등급제를 보존하고 표시 시점에 해석한다 (#208).
+//
+// 왜 필요한가:
+//   학생 type(학년)이 바뀌면(진급·재수 전환) 내신 등급제가 5↔9로 바뀐다. 그런데
+//   과거 성적을 학생의 *현재* 등급제로 해석하면 고2 때 받은 5등급제 3등급이
+//   9등급제 3등급으로 둔갑한다 — 백분위로 치면 전혀 다른 성취다. 이건 표시 버그가
+//   아니라 위조다.
+//
+//   변환(5↔9 환산)도 답이 아니다. 등급은 누적 백분위 구간의 이름이라 환산은
+//   정보 손실이고, 환산값을 "그 학생이 받은 등급"으로 보여주는 순간 역시 위조다.
+//
+//   그래서 정답은 보존이다: grades.grade_system(p143)에 기록 시점 등급제를 각인하고,
+//   표시·검증은 학생의 현재 type이 아니라 그 값을 읽는다.
+//
+// 등급제 판정 규칙(SQL p143과 1:1로 유지할 것):
+//   - report_type이 'mock'(학평·모평) | 'suneung' → 항상 g9.
+//     모의고사·수능은 학년 무관 9등급 상대평가다(lib/grade-entry.ts 헤더 참고).
+//     고1·2가 5등급제라고 해서 모의고사 등급이 5등급제가 되지 않는다.
+//   - 'naesin' 또는 NULL → 학생 type 기준. NULL을 내신으로 보는 건
+//     p120_backfill_absolute_subject_ranks.sql의 선례(온보딩 입력 행은 report_type이 없다).
+//
+// 날짜·학년도 리터럴 없음(골든룰 1) — 등급제 판정은 gradeContext만 경유한다.
+// ══════════════════════════════════════════════════════════════
+import {
+  gradeContext,
+  maxGrade,
+  GRADE_SYSTEM_LABEL,
+  type GradeSystem,
+  type StudentType,
+} from '@/lib/grade-system';
+
+/** 성적표 종류. grades.report_type과 1:1 (p90). */
+export type GradeReportType = 'mock' | 'naesin' | 'suneung';
+
+/** 등급제 해석에 필요한 성적 행의 최소 형태. */
+export interface GradeProvenanceRow {
+  /** p143에서 각인된 기록 시점 등급제. NULL=레거시(미각인) → studentType으로 폴백. */
+  grade_system?: GradeSystem | null;
+  report_type?: GradeReportType | null;
+}
+
+/** 학년 유형 → 내신 등급제 (고1·2 = g5, 고3·N수 = g9). */
+export function gradeSystemForType(type: StudentType): GradeSystem {
+  return gradeContext(type).gradeSystem;
+}
+
+/**
+ * 성적을 *기록하는 시점*에 각인할 등급제.
+ * 모의고사·수능은 학년 무관 9등급제, 내신(및 종류 미지정)은 학생 학년 기준.
+ *
+ * 쓰기 경로(/api/grades, /api/academy-admin/grades, /api/students/onboarding)는
+ * 반드시 이 함수로 grade_system을 채워야 한다 — 한 번 놓치면 진급 후 복원 불가다.
+ */
+export function stampGradeSystem(
+  reportType: GradeReportType | null | undefined,
+  studentType: StudentType
+): GradeSystem {
+  if (reportType === 'mock' || reportType === 'suneung') return 'g9';
+  return gradeSystemForType(studentType);
+}
+
+/**
+ * 성적 행을 *표시·검증할 때* 쓸 등급제.
+ * 각인값이 있으면 무조건 그것을 쓴다 — 학생의 현재 학년으로 덮어쓰지 않는다.
+ * 각인값이 없는 레거시 행만 학생 현재 학년으로 폴백한다(추정임을 아는 폴백).
+ */
+export function gradeSystemForRecord(
+  row: GradeProvenanceRow,
+  studentType: StudentType
+): GradeSystem {
+  return row.grade_system ?? stampGradeSystem(row.report_type, studentType);
+}
+
+/** 각인값이 없어 학생의 현재 학년으로 추정한 행인가(=진급 시 위조 위험이 남은 행). */
+export function isGradeSystemInferred(row: GradeProvenanceRow): boolean {
+  return row.grade_system == null;
+}
+
+/** 성적 행 기준 등급 상한(1~max). 입력 검증·표시 밴드 계산의 단일 출처. */
+export function maxGradeForRecord(
+  row: GradeProvenanceRow,
+  studentType: StudentType
+): number {
+  return maxGrade(gradeSystemForRecord(row, studentType));
+}
+
+/**
+ * 저장하려는 등급이 그 성적표 종류·학년의 등급제 범위 안인가.
+ * 위반이면 사용자에게 보여줄 한국어 사유, 통과면 null.
+ *
+ * 학생 자가 입력(/api/grades)과 학원장 입력(/api/academy-admin/grades)이 같은 규칙을
+ * 써야 한다 — 한쪽에만 상한이 있으면 고1·2 학생이 자기 내신에 6~9등급을 저장할 수 있다.
+ */
+export function gradeRangeError(
+  grade: number | null | undefined,
+  reportType: GradeReportType | null | undefined,
+  studentType: StudentType
+): string | null {
+  if (grade == null) return null;
+  const system = stampGradeSystem(reportType, studentType);
+  const max = maxGrade(system);
+  if (grade >= 1 && grade <= max) return null;
+  const what = system === 'g9' && reportType !== 'naesin' && reportType != null
+    ? '모의고사·수능'
+    : '이 학생의 내신';
+  return `${what}은 ${GRADE_SYSTEM_LABEL[system]}입니다. 1~${max} 범위로 입력하세요.`;
+}
+
+/** 성적 행의 등급제 라벨("5등급제" / "9등급제"). */
+export function gradeSystemLabelForRecord(
+  row: GradeProvenanceRow,
+  studentType: StudentType
+): string {
+  return GRADE_SYSTEM_LABEL[gradeSystemForRecord(row, studentType)];
+}
+
+/**
+ * 등급 한 줄 표기 — 성적 행의 등급제가 학생의 현재 등급제와 다를 때만 등급제를 병기한다.
+ * 예: 고3(9등급제) 학생의 고2 시절 내신 → "3등급(5등급제)".
+ *
+ * 숫자는 절대 환산하지 않는다. 병기는 재해석을 막기 위한 최소 장치다 —
+ * 프롬프트든 화면이든, 맥락 없는 "3등급"은 읽는 쪽(모델이든 사람이든)이
+ * 현재 등급제로 해석해 버린다.
+ */
+export function gradeDisplayLabel(
+  grade: number,
+  row: GradeProvenanceRow,
+  studentType: StudentType
+): string {
+  const rowSystem = gradeSystemForRecord(row, studentType);
+  const suffix =
+    rowSystem !== gradeSystemForType(studentType) ? `(${GRADE_SYSTEM_LABEL[rowSystem]})` : '';
+  return `${grade}등급${suffix}`;
+}
+
+/**
+ * 등급 표시 밴드(상위/중위/하위) — 등급제에 맞춰 경계를 스케일한다.
+ * 9등급제의 `<=2 / <=4` 경계를 5등급제에 그대로 쓰면 5등급 학생 거의 전원이
+ * '하위'로 찍힌다(누적 백분위가 전혀 다르다). 경계는 max의 비율로 잡는다.
+ */
+export function gradeBand(grade: number, system: GradeSystem): 'top' | 'mid' | 'low' {
+  // g9: <=2 상위, <=4 중위 / g5: <=1 상위, <=3 중위 — 누적 백분위 대략 11%·40% 선.
+  const topCut = system === 'g5' ? 1 : 2;
+  const midCut = system === 'g5' ? 3 : 4;
+  if (grade <= topCut) return 'top';
+  if (grade <= midCut) return 'mid';
+  return 'low';
+}
