index 00000000..0e479664
--- /dev/null
+++ b/sql/p143_student_type_promotion.sql
@@ -0,0 +1,185 @@
+-- ══════════════════════════════════════════════════════════════
+-- p143 — 학년(students.type) 변경 = 진급 이벤트 (#208)
+--
+-- 배경: 학생 type(high1|high2|high3|nsu)은 온보딩 upsert 말고는 바꿀 길이 없었다.
+--   type 변경은 단순 필드 수정이 아니라 진급 이벤트다 — 내신 등급제(5↔9)·D-day 기준
+--   학년도·계획 캐시가 연쇄로 바뀐다. 이 마이그레이션은 그 이벤트를 안전하게 만드는
+--   두 가지를 세운다.
+--
+--   1) grades.grade_system — 성적 행에 "기록 당시의 등급제"를 각인한다.
+--      type이 바뀌면 과거 성적의 등급제를 더 이상 유도할 수 없다. 변환(5↔9 환산)은
+--      정보 손실이자 위조이므로 하지 않는다 — 원본 등급제를 행에 보존하고
+--      표시 시점에 그 값으로 해석한다(lib/grade-provenance.ts).
+--
+--   2) student_type_transitions — 모든 학년 변경의 감사 가능한 이력.
+--      오조작 복구(되돌리기)의 근거이자, 각 전환이 등급제를 바꿨는지의 기록.
+--
+-- ⚠️ 등급제 판정 규칙(코드와 1:1 — lib/grade-provenance.ts):
+--      report_type IN ('mock','suneung')  → 항상 g9  (모의고사·수능은 학년 무관 9등급 상대평가)
+--      report_type = 'naesin' 또는 NULL   → 학생 type 기준 (high1|high2 → g5, 그 외 g9)
+--    NULL을 내신으로 취급하는 것은 p120_backfill_absolute_subject_ranks.sql의 선례를 따른다
+--    (온보딩 입력 행은 report_type을 쓰지 않는다).
+--
+-- ══════════════════════════════════════════════════════════════
+-- ⚠️⚠️ 아래 백필은 이 마이그레이션에서 딱 한 번만 유효하다 — 재실행 금지.
+-- ══════════════════════════════════════════════════════════════
+-- 백필은 "현재 students.type"으로 과거 성적의 등급제를 결정한다. 이게 추정이 아니라
+-- 사실인 이유는 단 하나다: **오늘까지 학생 type을 바꾸는 경로가 존재한 적이 없었다**
+-- (온보딩 upsert 재실행 제외). 그래서 현재 type == 그 성적을 기록하던 시점의 type이다.
+--
+-- 그런데 **이 전제는 #208이 머지되는 순간 거짓이 된다.** 진급 라우트
+-- (/api/students/promotion)가 바로 그 "type을 바꾸는 경로"이기 때문이다. 그 뒤로는
+-- 현재 type이 과거 성적의 등급제와 다를 수 있으므로, 이 UPDATE를 다시 돌리면 진급한
+-- 학생의 과거 성적이 새 학년 기준으로 덮여 **정확히 이 마이그레이션이 막으려던 위조가
+-- 일어난다.** (WHERE grade_system IS NULL 가드가 이미 각인된 행을 보호하니 그대로
+-- 재실행하는 것 자체는 무해하지만, 가드를 지우거나 컬럼을 리셋한 뒤 돌리면 위조다.)
+--
+-- 그래서 이 시점 이후로는 "NULL 행을 만들지 않을 책임"이 코드로 넘어간다:
+--   1) 세 쓰기 경로가 저장 시점에 직접 각인한다 — /api/grades ·
+--      /api/academy-admin/grades · /api/students/onboarding
+--      (전부 lib/grade-provenance.ts의 stampGradeSystem 경유)
+--   2) 진급 라우트가 type을 바꾸기 **직전에** 남은 NULL 행을 각인하고,
+--      각인이 실패하면 type을 바꾸지 않고 중단한다 — 바꾼 뒤엔 복원이 불가능하므로.
+--      순서·실패 모드는 tests/promotion-order-contract.test.ts가 잠근다.
+--
+-- 적용 직전 라이브 실측(2026-07-27, 서비스롤 read-only 조회) — 백필·CHECK 근거:
+--   · grades 총 299행(등급 있는 행 288), report_type IS NULL 264행(p120 선례대로 내신 취급)
+--   · 각인 규칙 적용 시 g5 152행(최대 등급 4) / g9 147행(최대 등급 5)
+--   · grades_grade_system_range_check 위반 행 **0건**
+--     → CHECK를 바로 VALIDATE 상태로 걸어도 기존 학생의 쓰기가 막히지 않는다.
+--
+-- ⚠️ 수동 적용(레포 컨벤션): Supabase SQL Editor에서 번호 순서로 실행. 재실행 안전(idempotent).
+--    Supabase SQL Editor는 statement 단위 autocommit이므로(p124·p142 선례) 전체를
+--    BEGIN/COMMIT으로 감싼다 — 컬럼만 추가되고 백필이 실패한 "반쪽 적용"이 남으면
+--    그 상태에서 성적 쓰기가 각인 없이 흘러 위조 창이 열린다.
+-- ══════════════════════════════════════════════════════════════
+
+BEGIN;
+
+-- ──────────────────────────────────────────────
+-- 1. grades.grade_system — 기록 시점 등급제 각인
+-- ──────────────────────────────────────────────
+ALTER TABLE public.grades
+  ADD COLUMN IF NOT EXISTS grade_system TEXT CHECK (grade_system IN ('g5', 'g9'));
+
+COMMENT ON COLUMN public.grades.grade_system IS
+  '이 성적이 기록될 당시의 등급제(g5=5등급제 / g9=9등급제). NULL=미각인(레거시). '
+  '학생의 현재 type이 아니라 이 값으로 해석한다 — 진급 후에도 과거 등급이 위조되지 않게 하는 출처 보존 컬럼(#208).';
+
+-- 백필: 이미 있는 행에 각인. grade_system이 NULL인 행만 건드린다(재실행 안전).
+UPDATE public.grades g
+SET grade_system = CASE
+      WHEN g.report_type IN ('mock', 'suneung') THEN 'g9'
+      WHEN s.type IN ('high1', 'high2') THEN 'g5'
+      ELSE 'g9'
+    END
+FROM public.students s
+WHERE s.id = g.student_id
+  AND g.grade_system IS NULL;
+
+-- 방어층: 각인된 등급제의 상한을 넘는 등급 저장 금지.
+--   기존 grades_grade_check(1~9)와 겹쳐 g5 행은 1~5로 좁혀진다.
+--   NULL grade / NULL grade_system(레거시)은 통과시킨다.
+ALTER TABLE public.grades DROP CONSTRAINT IF EXISTS grades_grade_system_range_check;
+ALTER TABLE public.grades
+  ADD CONSTRAINT grades_grade_system_range_check
+  CHECK (
+    grade IS NULL
+    OR grade_system IS NULL
+    OR grade <= CASE WHEN grade_system = 'g5' THEN 5 ELSE 9 END
+  );
+
+-- ──────────────────────────────────────────────
+-- 2. student_type_transitions — 학년 변경 이력(감사·되돌리기 근거)
+-- ──────────────────────────────────────────────
+CREATE TABLE IF NOT EXISTS public.student_type_transitions (
+  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
+  student_id        UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE,
+  from_type         TEXT NOT NULL CHECK (from_type IN ('high1', 'high2', 'high3', 'nsu')),
+  to_type           TEXT NOT NULL CHECK (to_type   IN ('high1', 'high2', 'high3', 'nsu')),
+  -- promotion=정상 진급(고1→고2, 고2→고3) / retake=재수 전환(고3→N수) /
+  -- correction=재분류·오입력 정정(역방향 포함) / revert=직전 전환 되돌리기
+  kind              TEXT NOT NULL CHECK (kind IN ('promotion', 'retake', 'correction', 'revert')),
+  -- 전환 전후의 내신 등급제. 성적 해석이 실제로 바뀌었는지 이력만 보고 판단할 수 있게 남긴다.
+  from_grade_system TEXT CHECK (from_grade_system IN ('g5', 'g9')),
+  to_grade_system   TEXT CHECK (to_grade_system   IN ('g5', 'g9')),
+  actor_id          UUID REFERENCES public.users(id) ON DELETE SET NULL,
+  -- 전환을 실행한 주체의 역할(student=본인 / academy_admin=학원장 / admin·teacher=운영자).
+  actor_role        TEXT,
+  reason            TEXT,
+  -- revert일 때 되돌린 원본 전환. 되돌리기 쌍을 이력에서 짝지을 수 있게.
+  reverted_transition_id UUID REFERENCES public.student_type_transitions(id) ON DELETE SET NULL,
+  -- 각인 결과 등 부수 정보(stamped_grade_rows, cleared_overrides …)
+  metadata          JSONB NOT NULL DEFAULT '{}',
+  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
+  -- 무의미한 no-op 전환 차단(같은 학년으로의 "변경"은 이벤트가 아니다).
+  CONSTRAINT student_type_transitions_actually_changes CHECK (from_type <> to_type)
+);
+
+COMMENT ON TABLE public.student_type_transitions IS
+  '학년(students.type) 변경 이력 = 진급 이벤트 감사 로그(#208). 되돌리기의 근거이자 '
+  '등급제 전환 여부의 기록. 쓰기는 service-role(API)만 — RLS 정책은 read만 연다.';
+
+-- 학생별 최신순 조회(이력 UI·되돌리기 대상 판정)가 유일한 접근 패턴.
+CREATE INDEX IF NOT EXISTS idx_student_type_transitions_student
+  ON public.student_type_transitions(student_id, created_at DESC);
+
+-- ──────────────────────────────────────────────
+-- RLS — 삼중 패턴(p40 daily_observations 미러). 쓰기는 service-role만(정책 없음).
+-- ──────────────────────────────────────────────
+ALTER TABLE public.student_type_transitions ENABLE ROW LEVEL SECURITY;
+
+-- 학생 본인 read
+DROP POLICY IF EXISTS student_type_transitions_student_select ON public.student_type_transitions;
+CREATE POLICY student_type_transitions_student_select ON public.student_type_transitions
+  FOR SELECT
+  USING (student_id IN (SELECT id FROM public.students WHERE user_id = auth.uid()));
+
+-- 학부모(verified) read
+DROP POLICY IF EXISTS student_type_transitions_parent_select ON public.student_type_transitions;
+CREATE POLICY student_type_transitions_parent_select ON public.student_type_transitions
+  FOR SELECT
+  USING (student_id IN (
+    SELECT student_id FROM public.parent_links
+    WHERE parent_id = auth.uid() AND verified = TRUE));
+
+-- 학원장(소속 학원의 active 관리자) read
+DROP POLICY IF EXISTS student_type_transitions_academy_select ON public.student_type_transitions;
+CREATE POLICY student_type_transitions_academy_select ON public.student_type_transitions
+  FOR SELECT
+  USING (student_id IN (
+    SELECT s.id FROM public.students s
+    JOIN public.academy_admins aa ON aa.academy_id = s.academy_id
+    WHERE aa.user_id = auth.uid() AND aa.status = 'active'));
+
+-- ──────────────────────────────────────────────
+-- 검증 — 실패하면 트랜잭션을 되돌린다(반쪽 적용 금지)
+-- ──────────────────────────────────────────────
+DO $$
+DECLARE
+  v_unstamped INT;
+  v_violations INT;
+BEGIN
+  -- 백필이 모든 행을 각인했는가. 남아 있으면 이후 표시가 "현재 학년 폴백"으로 흘러
+  -- 진급 후 위조가 재발한다 — 조용히 넘기지 않는다.
+  SELECT COUNT(*) INTO v_unstamped FROM public.grades WHERE grade_system IS NULL;
+  IF v_unstamped > 0 THEN
+    RAISE EXCEPTION 'p143 중단: grades.grade_system 미각인 행이 %건 남았다(0이어야 한다)', v_unstamped;
+  END IF;
+
+  -- 각인된 등급제 기준 상한을 넘는 등급이 남았는가(CHECK가 실제로 유효한지 재확인).
+  SELECT COUNT(*) INTO v_violations FROM public.grades
+   WHERE grade IS NOT NULL AND grade_system IS NOT NULL
+     AND grade > CASE WHEN grade_system = 'g5' THEN 5 ELSE 9 END;
+  IF v_violations > 0 THEN
+    RAISE EXCEPTION 'p143 중단: 등급제 상한 위반 행 %건', v_violations;
+  END IF;
+
+  RAISE NOTICE 'p143 OK: grades 전 행 각인 완료, 상한 위반 0건';
+END $$;
+
+COMMIT;
+
+-- 확인 쿼리:
+--   SELECT grade_system, report_type, COUNT(*), MAX(grade) FROM public.grades GROUP BY 1,2 ORDER BY 1,2;
+--   SELECT * FROM public.student_type_transitions ORDER BY created_at DESC LIMIT 10;
