+// ══════════════════════════════════════════════════════════════
+// tests/grade-provenance.test.ts
+// #208 — 진급(학년 변경) 시 기존 성적이 위조되지 않는가.
+//
+// 이 파일의 핵심 계약 하나: **성적 행에 각인된 등급제는 학생의 현재 학년으로
+// 절대 덮이지 않는다.** 고2(5등급제)에서 받은 3등급이 고3(9등급제)에서
+// 9등급제 3등급으로 읽히면 백분위가 전혀 다른 성취로 둔갑한다 — 표시 버그가
+// 아니라 위조다. 그래서 변환도, 재해석도 하지 않고 원본 등급제를 보존한다.
+// ══════════════════════════════════════════════════════════════
+import { describe, it, expect } from 'vitest';
+import {
+  stampGradeSystem,
+  gradeSystemForRecord,
+  gradeSystemForType,
+  gradeRangeError,
+  gradeBand,
+  isGradeSystemInferred,
+  maxGradeForRecord,
+  gradeSystemLabelForRecord,
+  gradeDisplayLabel,
+} from '@/lib/grade-provenance';
+import type { StudentType } from '@/lib/grade-system';
+
+describe('stampGradeSystem — 기록 시점 등급제 각인', () => {
+  it('내신은 학년 기준 — 고1·2는 g5, 고3·N수는 g9', () => {
+    expect(stampGradeSystem('naesin', 'high1')).toBe('g5');
+    expect(stampGradeSystem('naesin', 'high2')).toBe('g5');
+    expect(stampGradeSystem('naesin', 'high3')).toBe('g9');
+    expect(stampGradeSystem('naesin', 'nsu')).toBe('g9');
+  });
+
+  it('모의고사·수능은 학년 무관 9등급제 — 고1·2도 g9로 각인한다', () => {
+    // 고1·2가 5등급제라고 해서 모의고사 등급까지 5등급제가 되지는 않는다.
+    // 학평·모평·수능은 전 학년 공통 9등급 상대평가다.
+    for (const type of ['high1', 'high2', 'high3', 'nsu'] as StudentType[]) {
+      expect(stampGradeSystem('mock', type)).toBe('g9');
+      expect(stampGradeSystem('suneung', type)).toBe('g9');
+    }
+  });
+
+  it('성적표 종류 미지정(온보딩 입력)은 내신으로 취급한다', () => {
+    // p120_backfill_absolute_subject_ranks.sql의 선례와 같은 규칙.
+    expect(stampGradeSystem(null, 'high1')).toBe('g5');
+    expect(stampGradeSystem(undefined, 'high3')).toBe('g9');
+  });
+});
+
+describe('gradeSystemForRecord — 표시 시점 해석 (위조 방지의 핵심)', () => {
+  it('★ 진급해도 각인된 등급제를 학생의 현재 학년으로 덮어쓰지 않는다', () => {
+    // 고2(5등급제)에서 받은 내신 3등급. 학생은 이후 고3(9등급제)이 되었다.
+    const 고2때_받은_내신 = { grade_system: 'g5' as const, report_type: 'naesin' as const };
+
+    // 학생의 현재 학년이 무엇이든 이 성적은 영원히 5등급제로 읽혀야 한다.
+    expect(gradeSystemForRecord(고2때_받은_내신, 'high3')).toBe('g5');
+    expect(gradeSystemForRecord(고2때_받은_내신, 'nsu')).toBe('g5');
+    expect(gradeSystemForRecord(고2때_받은_내신, 'high1')).toBe('g5');
+  });
+
+  it('★ 반대 방향도 마찬가지 — 고3(9등급제) 성적은 되돌려도 9등급제다', () => {
+    // 오조작으로 고3 → 고2로 되돌린 경우에도 이미 기록된 9등급제 성적은 그대로다.
+    const 고3때_받은_내신 = { grade_system: 'g9' as const, report_type: 'naesin' as const };
+    expect(gradeSystemForRecord(고3때_받은_내신, 'high2')).toBe('g9');
+  });
+
+  it('★ 5등급제로는 표현할 수 없는 등급(6~9)이 각인 덕에 살아남는다', () => {
+    // 고3이 받은 내신 7등급. 학생이 고2로 정정되어도 7등급은 9등급제 7등급이지
+    // 5등급제 7등급(존재하지 않는 값)이 아니다. 각인이 없으면 이 행은 해석 불능이 된다.
+    const row = { grade_system: 'g9' as const, report_type: 'naesin' as const };
+    expect(maxGradeForRecord(row, 'high2')).toBe(9);
+    expect(gradeSystemLabelForRecord(row, 'high2')).toBe('9등급제');
+  });
+
+  it('각인값이 없는 레거시 행만 현재 학년으로 폴백한다', () => {
+    const legacy = { grade_system: null, report_type: 'naesin' as const };
+    expect(gradeSystemForRecord(legacy, 'high2')).toBe('g5');
+    expect(gradeSystemForRecord(legacy, 'high3')).toBe('g9');
+    expect(isGradeSystemInferred(legacy)).toBe(true);
+    expect(isGradeSystemInferred({ grade_system: 'g5', report_type: null })).toBe(false);
+  });
+
+  it('레거시 모의고사 행은 학년과 무관하게 g9로 폴백한다', () => {
+    const legacyMock = { grade_system: null, report_type: 'mock' as const };
+    expect(gradeSystemForRecord(legacyMock, 'high1')).toBe('g9');
+  });
+});
+
+describe('gradeSystemForType', () => {
+  it('gradeContext와 같은 판정을 낸다 (구현이 둘이 아님)', () => {
+    expect(gradeSystemForType('high1')).toBe('g5');
+    expect(gradeSystemForType('high2')).toBe('g5');
+    expect(gradeSystemForType('high3')).toBe('g9');
+    expect(gradeSystemForType('nsu')).toBe('g9');
+  });
+});
+
+describe('gradeRangeError — 저장 전 등급 상한 검증', () => {
+  it('고1·2 내신에 6~9등급을 거부한다 (자가 입력 라우트의 구멍이었다)', () => {
+    expect(gradeRangeError(6, 'naesin', 'high1')).toMatch(/5등급제/);
+    expect(gradeRangeError(9, 'naesin', 'high2')).toMatch(/1~5/);
+    expect(gradeRangeError(5, 'naesin', 'high1')).toBeNull();
+  });
+
+  it('고1·2라도 모의고사·수능은 9등급까지 허용한다', () => {
+    expect(gradeRangeError(9, 'mock', 'high1')).toBeNull();
+    expect(gradeRangeError(7, 'suneung', 'high2')).toBeNull();
+  });
+
+  it('성적표 종류 미지정(온보딩)은 내신 상한을 적용한다', () => {
+    expect(gradeRangeError(7, null, 'high1')).toMatch(/5등급제/);
+    expect(gradeRangeError(7, null, 'high3')).toBeNull();
+  });
+
+  it('고3·N수 내신은 9등급까지, 0·10등급은 거부', () => {
+    expect(gradeRangeError(9, 'naesin', 'high3')).toBeNull();
+    expect(gradeRangeError(0, 'naesin', 'high3')).not.toBeNull();
+    expect(gradeRangeError(10, 'mock', 'nsu')).not.toBeNull();
+  });
+
+  it('등급이 없으면(원점수만 입력) 통과시킨다', () => {
+    expect(gradeRangeError(null, 'naesin', 'high1')).toBeNull();
+    expect(gradeRangeError(undefined, 'mock', 'high3')).toBeNull();
+  });
+});
+
+describe('gradeDisplayLabel — 프롬프트·화면 공용 등급 표기', () => {
+  it('현재 등급제와 같으면 등급제를 병기하지 않는다 (평소엔 군더더기)', () => {
+    expect(gradeDisplayLabel(3, { grade_system: 'g9', report_type: 'naesin' }, 'high3')).toBe('3등급');
+    expect(gradeDisplayLabel(2, { grade_system: 'g5', report_type: 'naesin' }, 'high2')).toBe('2등급');
+  });
+
+  it('★ 진급 후 과거 성적에는 원래 등급제를 병기한다', () => {
+    // 고2 때 받은 5등급제 3등급. 고3이 된 지금 그냥 "3등급"으로 프롬프트에 넣으면
+    // 시스템 프롬프트가 "고3=9등급제"라 선언한 탓에 모델이 9등급제 3등급으로 읽는다.
+    expect(gradeDisplayLabel(3, { grade_system: 'g5', report_type: 'naesin' }, 'high3')).toBe(
+      '3등급(5등급제)'
+    );
+  });
+
+  it('★ 숫자를 환산하지 않는다 — 등급 값은 원본 그대로', () => {
+    // 5등급제 3등급을 9등급제 척도로 "환산"하면 대략 5~6등급이 된다. 그런 숫자는
+    // 학생이 받은 적 없는 등급이므로 절대 만들어내지 않는다.
+    expect(gradeDisplayLabel(3, { grade_system: 'g5', report_type: 'naesin' }, 'high3')).toContain('3등급');
+    expect(gradeDisplayLabel(3, { grade_system: 'g5', report_type: 'naesin' }, 'high3')).not.toContain('5등급(');
+  });
+
+  it('고1·2의 모의고사는 9등급제라 병기된다', () => {
+    // 고1(현재 5등급제)의 모의고사 4등급은 9등급제 값이다 — 병기가 있어야 정확하다.
+    expect(gradeDisplayLabel(4, { grade_system: 'g9', report_type: 'mock' }, 'high1')).toBe(
+      '4등급(9등급제)'
+    );
+  });
+
+  it('레거시(미각인) 행은 현재 학년으로 폴백해 병기하지 않는다', () => {
+    expect(gradeDisplayLabel(3, { grade_system: null, report_type: 'naesin' }, 'high3')).toBe('3등급');
+  });
+});
+
+describe('gradeBand — 등급제별 표시 밴드', () => {
+  it('9등급제 경계를 5등급제에 그대로 쓰지 않는다', () => {
+    // 9등급제: 1~2 상위 / 3~4 중위 / 5~9 하위
+    expect(gradeBand(2, 'g9')).toBe('top');
+    expect(gradeBand(4, 'g9')).toBe('mid');
+    expect(gradeBand(5, 'g9')).toBe('low');
+    // 5등급제: 1 상위 / 2~3 중위 / 4~5 하위.
+    // 9등급제 경계(<=2 상위, <=4 중위)를 그대로 쓰면 5등급제 학생 대부분이
+    // '상위·중위'로 뭉개져 밴드가 아무 정보도 주지 못한다.
+    expect(gradeBand(1, 'g5')).toBe('top');
+    expect(gradeBand(2, 'g5')).toBe('mid');
+    expect(gradeBand(3, 'g5')).toBe('mid');
+    expect(gradeBand(4, 'g5')).toBe('low');
+    expect(gradeBand(5, 'g5')).toBe('low');
+  });
+
+  it('같은 숫자 등급이 등급제에 따라 다른 밴드로 읽힌다 (환산 금지의 이유)', () => {
+    // 5등급제 2등급(누적 ~34%)과 9등급제 2등급(누적 ~11%)은 전혀 다른 성취다.
+    expect(gradeBand(2, 'g5')).not.toBe(gradeBand(2, 'g9'));
+  });
+});
