+// ══════════════════════════════════════════════════════════════
+// tests/promotion.test.ts
+// #208 — 학년(students.type) 변경 = 진급 이벤트의 도메인 규칙.
+//
+// 검증 목표:
+//   1) 전환 종류 분류(진급/재수/정정/되돌리기) — nsu 경로 포함.
+//   2) 등급제 전환을 숨기지 않고 드러낸다(사용자 확인 대상).
+//   3) 정정(correction)은 사유 없이 통과할 수 없다.
+//   4) 코호트 밴드를 넘으면 학습 단계 보정을 비운다.
+//   5) 요청 스키마가 화이트리스트 밖 필드를 거부한다.
+// ══════════════════════════════════════════════════════════════
+import { describe, it, expect } from 'vitest';
+import {
+  PromotionRequestSchema,
+  classifyTransition,
+  transitionRequiresReason,
+  crossesCohortBand,
+  gradeSystemChange,
+  describeTransition,
+  validatePromotion,
+} from '@/lib/promotion';
+
+describe('classifyTransition', () => {
+  it('정상 진급은 promotion', () => {
+    expect(classifyTransition('high1', 'high2')).toBe('promotion');
+    expect(classifyTransition('high2', 'high3')).toBe('promotion');
+  });
+
+  it('고3 → N수는 retake (재수도 진급의 일종이다)', () => {
+    expect(classifyTransition('high3', 'nsu')).toBe('retake');
+  });
+
+  it('건너뛰기·역방향·그 외는 correction', () => {
+    expect(classifyTransition('high1', 'high3')).toBe('correction');
+    expect(classifyTransition('high3', 'high2')).toBe('correction');
+    expect(classifyTransition('nsu', 'high3')).toBe('correction');
+    expect(classifyTransition('high1', 'nsu')).toBe('correction');
+  });
+
+  it('직전 전환을 정확히 되돌리면 revert로 분류한다', () => {
+    // 고2→고3 진급을 잘못 눌렀다 → 고3→고2는 정정이 아니라 되돌리기다.
+    expect(classifyTransition('high3', 'high2', true)).toBe('revert');
+  });
+});
+
+describe('transitionRequiresReason', () => {
+  it('정정만 사유를 요구한다 — 진급·재수·되돌리기는 흐름상 자명하다', () => {
+    expect(transitionRequiresReason('correction')).toBe(true);
+    expect(transitionRequiresReason('promotion')).toBe(false);
+    expect(transitionRequiresReason('retake')).toBe(false);
+    expect(transitionRequiresReason('revert')).toBe(false);
+  });
+});
+
+describe('crossesCohortBand', () => {
+  it('고1·2(2022 개정 세대) ↔ 고3·N수(2015 개정 세대) 경계를 감지한다', () => {
+    expect(crossesCohortBand('high2', 'high3')).toBe(true);
+    expect(crossesCohortBand('high3', 'high2')).toBe(true);
+    // 밴드 안쪽 이동은 어휘·과목 풀이 그대로다.
+    expect(crossesCohortBand('high1', 'high2')).toBe(false);
+    expect(crossesCohortBand('high3', 'nsu')).toBe(false);
+  });
+});
+
+describe('gradeSystemChange — 등급제 전환을 숨기지 않는다', () => {
+  it('고2 → 고3은 5등급제 → 9등급제 전환을 알린다', () => {
+    const c = gradeSystemChange('high2', 'high3');
+    expect(c.from).toBe('g5');
+    expect(c.to).toBe('g9');
+    expect(c.changed).toBe(true);
+    expect(c.notice).toMatch(/5등급제 → 9등급제/);
+  });
+
+  it('안내문은 기존 성적을 환산하지 않는다고 명시한다', () => {
+    // 이 문구가 사라지면 학생은 과거 등급이 재해석된다고 오해한다.
+    expect(gradeSystemChange('high2', 'high3').notice).toMatch(/환산하지 않습니다/);
+  });
+
+  it('고3 → N수는 등급제가 그대로라 알림이 없다', () => {
+    const c = gradeSystemChange('high3', 'nsu');
+    expect(c.changed).toBe(false);
+    expect(c.notice).toBeNull();
+  });
+
+  it('고1 → 고2도 등급제가 그대로다', () => {
+    expect(gradeSystemChange('high1', 'high2').changed).toBe(false);
+  });
+});
+
+describe('describeTransition', () => {
+  it('학년 라벨을 gradeContext에서 가져와 한 줄로 만든다', () => {
+    expect(describeTransition('high2', 'high3', 'promotion')).toBe('고2 → 고3 진급');
+    expect(describeTransition('high3', 'nsu', 'retake')).toBe('고3 → N수 재수 전환');
+    expect(describeTransition('high3', 'high2', 'revert')).toBe('고3 → 고2 되돌리기');
+  });
+});
+
+describe('validatePromotion', () => {
+  it('정상 진급을 통과시킨다', () => {
+    const r = validatePromotion({ from: 'high2', to: 'high3' });
+    expect(r.ok).toBe(true);
+    expect(r.kind).toBe('promotion');
+    expect(r.clearsStudyPhaseOverride).toBe(true); // 코호트 밴드를 넘는다
+  });
+
+  it('같은 학년으로의 변경은 이벤트가 아니다', () => {
+    const r = validatePromotion({ from: 'high3', to: 'high3' });
