+    expect(r.error).toMatch(/사유/);
+  });
+
+  it('정정도 사유가 있으면 통과한다 (오입력 정정 경로를 막지 않는다)', () => {
+    const r = validatePromotion({
+      from: 'high3',
+      to: 'high1',
+      reason: '온보딩에서 학년을 잘못 선택함',
+    });
+    expect(r.ok).toBe(true);
+    expect(r.kind).toBe('correction');
+  });
+
+  it('공백만 있는 사유는 사유가 아니다', () => {
+    expect(validatePromotion({ from: 'high3', to: 'high1', reason: '   ' }).ok).toBe(false);
+  });
+
+  it('되돌리기는 사유 없이 통과한다 (오조작 복구를 방해하지 않는다)', () => {
+    const r = validatePromotion({ from: 'high3', to: 'high2', isRevertOfLatest: true });
+    expect(r.ok).toBe(true);
+    expect(r.kind).toBe('revert');
+  });
+
+  it('재수 전환(고3→N수)은 사유 없이 통과하고 밴드를 넘지 않는다', () => {
+    const r = validatePromotion({ from: 'high3', to: 'nsu' });
+    expect(r.ok).toBe(true);
+    expect(r.kind).toBe('retake');
+    expect(r.clearsStudyPhaseOverride).toBe(false);
+  });
+});
+
+describe('PromotionRequestSchema', () => {
+  it('student_id 없이 to_type만으로 유효하다 (본인 변경)', () => {
+    expect(PromotionRequestSchema.safeParse({ to_type: 'high3' }).success).toBe(true);
+  });
+
+  it('알 수 없는 학년을 거부한다', () => {
+    expect(PromotionRequestSchema.safeParse({ to_type: 'middle3' }).success).toBe(false);
+  });
+
+  it('화이트리스트 밖 필드를 거부한다 (.strict())', () => {
+    // 이 라우트로 다른 학생 필드를 밀어 넣을 수 없어야 한다.
+    const r = PromotionRequestSchema.safeParse({ to_type: 'high3', target_university: 'sky' });
+    expect(r.success).toBe(false);
+  });
+
+  it('student_id는 uuid만 받는다', () => {
+    expect(
+      PromotionRequestSchema.safeParse({ to_type: 'high3', student_id: 'not-a-uuid' }).success
+    ).toBe(false);
+  });
+});
