+// ══════════════════════════════════════════════════════════════
+// lib/promotion.ts
+// 학년(students.type) 변경 = 진급 이벤트의 순수 도메인 로직 (#208).
+//
+// type 변경은 단순 필드 수정이 아니다. 내신 등급제(5↔9)·수능 D-day 기준 학년도·
+// 교육과정(2022/2015)·계획 캐시 지문이 한꺼번에 따라 움직인다. 그래서 프로필
+// 편집 화이트리스트(lib/profile-patch.ts)에서 type을 빼고 이 전용 경로로 분리했다.
+//
+// 이 모듈은 순수하다 — supabaseAdmin 등 서버 전용 모듈을 임포트하지 않으므로
+// 유닛테스트(node env)에서 직접 임포트할 수 있다. 배선은 API 라우트가 한다.
+//
+// ⚠️ 알려진 한계(이 티켓 범위 밖, 후속 필요):
+//   gradeContext는 학년→대입학년도를 리터럴로 갖고 있어 2026년 달력에서만 맞다.
+//   실제 불변량은 학년이 아니라 코호트(대입 학년도)다 — 2026년 고2는 2027년에
+//   고3이 되어도 여전히 2028 대입·5등급제다. 그래서 "진급하면 등급제가 바뀐다"는
+//   현재 코드의 동작이지 입시 제도의 진실이 아니다. 이 모듈은 그 동작을 숨기지
+//   않고 gradeSystemChange()로 드러내 사용자에게 확인시킨다.
+// ══════════════════════════════════════════════════════════════
+import { z } from 'zod';
+import { gradeContext, GRADE_SYSTEM_LABEL, type StudentType, type GradeSystem } from '@/lib/grade-system';
+import { gradeSystemForType } from '@/lib/grade-provenance';
+
+export const STUDENT_TYPES = ['high1', 'high2', 'high3', 'nsu'] as const;
+
+/**
+ * 전환 종류.
+ *   promotion  — 정상 진급(고1→고2, 고2→고3)
+ *   retake     — 재수 전환(고3→N수)
+ *   correction — 재분류·오입력 정정(역방향 포함). 루틴 이벤트가 아니므로 사유 필수.
+ *   revert     — 직전 전환 되돌리기(오조작 복구)
+ */
+export type TransitionKind = 'promotion' | 'retake' | 'correction' | 'revert';
+
+/** 요청 스키마. student_id 생략 시 세션 학생 본인. */
+export const PromotionRequestSchema = z
+  .object({
+    student_id: z.string().uuid().optional(),
+    to_type: z.enum(STUDENT_TYPES),
+    reason: z.string().max(300).optional(),
+  })
+  .strict();
+
+export type PromotionRequest = z.infer<typeof PromotionRequestSchema>;
+
+const PROMOTION_STEPS: Partial<Record<StudentType, StudentType>> = {
+  high1: 'high2',
+  high2: 'high3',
+};
+
+/**
+ * 전환 종류 판정. `isRevertOfLatest`는 "이 전환이 가장 최근 전환을 정확히 되돌리는가"로,
+ * 호출자가 이력을 조회해 넘긴다(순수성 유지).
+ */
+export function classifyTransition(
+  from: StudentType,
+  to: StudentType,
+  isRevertOfLatest = false
+): TransitionKind {
+  if (isRevertOfLatest) return 'revert';
+  if (PROMOTION_STEPS[from] === to) return 'promotion';
+  if (from === 'high3' && to === 'nsu') return 'retake';
+  return 'correction';
+}
+
+/**
+ * 사유가 필수인가. 정상 진급·재수·되돌리기는 흐름상 자명하지만,
+ * 재분류(correction)는 왜 바꿨는지가 남지 않으면 나중에 판단할 수 없다.
+ */
+export function transitionRequiresReason(kind: TransitionKind): boolean {
+  return kind === 'correction';
+}
+
+/**
+ * 코호트 밴드(고1·2 = 2022 개정/5등급제 세대 ↔ 고3·N수 = 2015 개정/9등급제 세대)를 넘는가.
+ * 넘으면 학습 단계 어휘(student-classifier의 HIGH12_PHASE_OPTIONS ↔ PHASE_OPTIONS)와
+ * 교육과정 과목 풀(2022 ↔ 2015)이 통째로 달라진다.
+ */
+export function crossesCohortBand(from: StudentType, to: StudentType): boolean {
+  const band = (t: StudentType) => (t === 'high1' || t === 'high2' ? 'new2028' : 'current');
+  return band(from) !== band(to);
+}
+
+export interface GradeSystemChange {
+  from: GradeSystem;
+  to: GradeSystem;
+  changed: boolean;
+  /** 사용자에게 보여줄 경고 문구. 안 바뀌면 null. */
+  notice: string | null;
+}
+
+/**
+ * 이 전환이 내신 등급제를 바꾸는가 — 바꾼다면 사용자에게 반드시 알려야 한다.
+ *
+ * 과거 성적은 각인된 등급제(grades.grade_system)로 계속 해석되므로 위조되지 않지만,
+ * 앞으로 입력하는 내신의 등급 범위가 달라진다.
+ */
+export function gradeSystemChange(from: StudentType, to: StudentType): GradeSystemChange {
+  const fromSystem = gradeSystemForType(from);
+  const toSystem = gradeSystemForType(to);
+  const changed = fromSystem !== toSystem;
+  return {
+    from: fromSystem,
+    to: toSystem,
+    changed,
+    notice: changed
+      ? `내신 등급제가 ${GRADE_SYSTEM_LABEL[fromSystem]} → ${GRADE_SYSTEM_LABEL[toSystem]}로 바뀝니다. ` +
+        `이미 기록된 성적은 입력 당시 등급제로 계속 표시되며 환산하지 않습니다.`
+      : null,
+  };
+}
+
+/** 전환 한 줄 설명("고2 → 고3 진급"). 이력 UI·감사 로그 공용. */
+export function describeTransition(
+  from: StudentType,
+  to: StudentType,
+  kind: TransitionKind
+): string {
+  const label: Record<TransitionKind, string> = {
+    promotion: '진급',
+    retake: '재수 전환',
+    correction: '학년 정정',
+    revert: '되돌리기',
+  };
+  return `${gradeContext(from).gradeLabelShort} → ${gradeContext(to).gradeLabelShort} ${label[kind]}`;
+}
+
+export interface PromotionValidation {
+  ok: boolean;
+  /** ok=false일 때 사용자에게 보여줄 이유. */
+  error: string | null;
+  kind: TransitionKind;
+  gradeSystem: GradeSystemChange;
+  /** 코호트 밴드를 넘어 학습 단계 보정(profile_overrides.study_phase)을 비워야 하는가. */
+  clearsStudyPhaseOverride: boolean;
+}
+
+/**
+ * 전환 가능 여부 + 파생 정보. 라우트는 이 결과만 보고 분기한다.
+ *
+ * 되돌리기·재분류를 포함해 모든 방향을 허용한다 — 오입력 정정 수요가 실재하고
+ * (온보딩에서 학년을 잘못 고른 학생), 막아 두면 지원팀이 DB를 직접 만지게 된다.
+ * 대신 correction은 사유를 강제하고 전 이력을 남긴다.
+ */
+export function validatePromotion(args: {
+  from: StudentType;
+  to: StudentType;
+  reason?: string | null;
+  isRevertOfLatest?: boolean;
+}): PromotionValidation {
+  const { from, to, reason, isRevertOfLatest = false } = args;
+  const kind = classifyTransition(from, to, isRevertOfLatest);
+  const gradeSystem = gradeSystemChange(from, to);
+  const clearsStudyPhaseOverride = crossesCohortBand(from, to);
+
+  if (from === to) {
+    return {
+      ok: false,
+      error: '이미 같은 학년입니다.',
+      kind,
+      gradeSystem,
+      clearsStudyPhaseOverride,
+    };
+  }
+  if (transitionRequiresReason(kind) && !reason?.trim()) {
+    return {
+      ok: false,
+      error: '학년 정정은 사유를 입력해야 합니다.',
+      kind,
+      gradeSystem,
+      clearsStudyPhaseOverride,
+    };
+  }
+  return { ok: true, error: null, kind, gradeSystem, clearsStudyPhaseOverride };
+}

