    24	/**
    25	 * 관측 알림 유실 방지(#180): fire-and-forget 관측 호출을 after()로 감싸 응답 flush 후 실행을 보장한다.
    26	 * 서버리스는 응답 반환 직후 인스턴스를 freeze할 수 있어 bare `void` 프로미스는 webhook flush 전에 끊길
    27	 * 수 있다 → after()로 응답 후 실행 보장. authErrorResponse의 after(report) 배선과 동일하며, 요청 스코프
    28	 * 밖(비-요청 컨텍스트)이면 after()가 throw하므로 즉시 폴백 실행한다. report는 절대 throw하지 않는다.
    29	 */
    30	export function reportAfter(report: () => void | Promise<void>): void {
    31	  const run = () => {
    32	    try {
    33	      return Promise.resolve(report());
    34	    } catch {
    35	      return Promise.resolve();
    36	    }
    37	  };
    38	  try {
    39	    after(run);
    40	  } catch {
    41	    void run();
    42	  }
    43	}
