    45	export function authErrorResponse(e: unknown): NextResponse {
    46	  if (e instanceof AuthError) {
    47	    return NextResponse.json({ error: e.message }, { status: e.status });
    48	  }
    49	  console.error('[auth] unexpected error:', e);
    50	  // 관측성: 처리되지 않은 예외는 곧 500. Postgres/RLS 오류(42P17류)는 별도 이벤트로 분류.
    51	  // #159-2: 즉시 500을 반환하는 지점이라 fire-and-forget webhook이 서버리스 종료로 유실될 수
    52	  //   있다 → after()로 응답 flush 후 실행 보장(요청 스코프 밖이면 즉시 폴백).
    53	  // #159-4: Postgres 케이스는 그동안 미사용이던 reportPostgresError로 배선(code/message/details/hint 일관).
    54	  const err = e as { message?: string; stack?: string };
    55	  const report = () => {
    56	    if (isPostgresError(e)) {
    57	      return reportPostgresError(e, { stack: err?.stack });
    58	    }
    59	    return reportCritical('server_error_500', { message: err?.message, stack: err?.stack });
    60	  };
    61	  reportAfter(report);
    62	  return NextResponse.json({ error: 'Server error' }, { status: 500 });
    63	}
