    71	/**
    72	 * 로그인된 사용자 반환. 없으면 401.
    73	 * getClaims()로 JWT를 로컬 검증(프로젝트가 비대칭 ES256 키 사용 → JWKS 전역 캐시로 네트워크 왕복 없음).
    74	 * getUser의 GoTrue 왕복을 제거. tradeoff: 폐기/로그아웃 access token이 만료(TTL)까지 로컬 유효.
    75	 */
    76	export async function requireUser(): Promise<AuthedUser> {
    77	  const supabase = await createServerSupabase();
    78	  const { data, error } = await supabase.auth.getClaims();
    79	  const claims = data?.claims;
    80	  if (error || !claims?.sub) throw new AuthError(401, 'Unauthorized');
    81	  return { id: claims.sub, email: (claims.email as string | undefined) ?? null };
    82	}
    83	
    84	/**
    85	 * RSC 페이지용: 로그인 사용자({id,email}) 또는 null. 페이지마다 redirect 대상이 달라 throw 대신 null 반환.
    86	 * requireUser와 동일하게 getClaims 로컬 검증(getUser 네트워크 왕복 없음).
    87	 */
    88	export async function getAuthedUser(): Promise<AuthedUser | null> {
    89	  const supabase = await createServerSupabase();
    90	  const { data } = await supabase.auth.getClaims();
    91	  const claims = data?.claims;
    92	  return claims?.sub
    93	    ? { id: claims.sub, email: (claims.email as string | undefined) ?? null }
    94	    : null;
    95	}
