   225	      console.error('[promotion POST] grade_system 각인 실패:', e);
   226	      // 각인에 실패한 채 type을 바꾸면 과거 성적의 등급제가 영구 소실된다 — 여기서 중단한다.
   227	      // 학년은 그대로 남으므로 재시도가 항상 올바른 값을 각인한다.
   228	      return NextResponse.json(
   229	        { error: '기존 성적의 등급제 보존에 실패해 학년을 변경하지 않았습니다. 잠시 후 다시 시도해 주세요.' },
   230	        { status: 500 }
   231	      );
   232	    }
   233	
   234	    // ── ② 학년 변경 ──
   235	    // 코호트 밴드를 넘으면 학습 단계 보정값의 어휘 자체가 달라진다(student-classifier
   236	    // HIGH12_PHASE_OPTIONS ↔ PHASE_OPTIONS) — 남겨 두면 존재하지 않는 단계로 표시된다.
   237	    const overrides = (student.profile_overrides ?? {}) as Record<string, unknown>;
   238	    const clearedOverrides: string[] = [];
   239	    const studentPatch: Record<string, unknown> = { type: to_type };
   240	    if (check.clearsStudyPhaseOverride && overrides.study_phase != null) {
   241	      const next = { ...overrides };
   242	      delete next.study_phase;
   243	      studentPatch.profile_overrides = next;
   244	      clearedOverrides.push('study_phase');
   245	    }
   246	
   247	    // CAS(compare-and-swap) — `.eq('type', fromType)`로 "읽은 그 상태일 때만" 쓴다.
   248	    // 각 문이 autocommit이라 두 요청이 같은 fromType을 읽으면 둘 다 검증을 통과하고,
   249	    // 최종 type은 마지막 write가 정하는데 두 전환 이력은 모두 같은 from_type으로 남아
   250	    // 이력이 실제 경로와 어긋난다(같은 요청 재시도도 중복 이력을 만든다).
   251	    // 0행이면 그사이 누가 학년을 바꿨다는 뜻이므로 409로 되돌린다(#740과 같은 패턴).
   252	    const { data: updatedRows, error: updErr } = await supabaseAdmin
   253	      .from('students')
   254	      .update(studentPatch)
   255	      .eq('id', studentId)
   256	      .eq('type', fromType)
   257	      .select('id');
   258	    if (updErr) {
   259	      console.error('[promotion POST] students update error:', updErr);
   260	      return NextResponse.json({ error: '학년 변경 저장 실패' }, { status: 500 });
   261	    }
   262	    if (!updatedRows || updatedRows.length === 0) {
   263	      // 각인은 이미 끝났고 무해하다(그 시점 type 기준으로 정확) — 학년만 안 바뀐 상태다.
   264	      return NextResponse.json(
   265	        {
   266	          error: '다른 곳에서 학년이 먼저 변경됐습니다. 최신 상태를 확인한 뒤 다시 시도해 주세요.',
   267	          code: 'PROMOTION_CONFLICT',
   268	        },
   269	        { status: 409 }
   270	      );
   271	    }
   272	
   273	    // ── ③ 프로필의 등급제 동기화 ──
   274	    // student_profiles.grade_system은 온보딩에서만 쓰이던 값이라 두면 학년과 어긋난다.
   275	    const { error: profErr } = await supabaseAdmin
   276	      .from('student_profiles')
   277	      .upsert(
   278	        { student_id: studentId, grade_system: gradeSystemForType(to_type) },
   279	        { onConflict: 'student_id' }
   280	      );
   281	    if (profErr) {
   282	      // 학년 변경 자체는 성공했다 — 실패를 삼키지 말고 로그만 남기고 계속(다음 저장에서 복구된다).
   283	      console.error('[promotion POST] student_profiles grade_system sync error:', profErr);
   284	    }
   285	
   286	    // ── ④ 이력 + 감사 로그 ──
   287	    const actorRole = await resolveActorRole(user.id, student.user_id ?? null);
   288	    const { data: transition, error: trErr } = await supabaseAdmin
   289	      .from('student_type_transitions')
   290	      .insert({
   291	        student_id: studentId,
   292	        from_type: fromType,
   293	        to_type,
   294	        kind: check.kind,
   295	        from_grade_system: check.gradeSystem.from,
   296	        to_grade_system: check.gradeSystem.to,
   297	        actor_id: user.id,
   298	        actor_role: actorRole,
   299	        reason: reason?.trim() || null,
   300	        reverted_transition_id: check.kind === 'revert' ? (latest?.id ?? null) : null,
   301	        metadata: { stamped_grade_rows: stampedGradeRows, cleared_overrides: clearedOverrides },
   302	      })
   303	      .select('id')
   304	      .maybeSingle();
   305	    if (trErr) {
   306	      console.error('[promotion POST] transition insert error:', trErr);
   307	    }
   308	
   309	    await supabaseAdmin
   310	      .from('audit_logs')
   311	      .insert({
   312	        actor_id: user.id,
   313	        action: 'student.type_change',
   314	        target_id: studentId,
   315	        metadata: {
   316	          from_type: fromType,
   317	          to_type,
   318	          kind: check.kind,
   319	          actor_role: actorRole,
   320	          grade_system_changed: check.gradeSystem.changed,
   321	          stamped_grade_rows: stampedGradeRows,
   322	          transition_id: transition?.id ?? null,
   323	        },
   324	      })
   325	      .then(
   326	        () => undefined,
   327	        () => undefined
   328	      );
   329	
   330	    // ── ⑤ 응답: 무엇이 자동으로 따라오고 무엇이 안 따라오는지 정직하게 알린다 ──
   331	    // 월간·분기·장기 계획은 캐시 지문에 type·phase 토큰이 있어 다음 생성 때 자동 무효화된다
   332	    // (lib/generate-plan.ts buildInputFingerprint). 일간 계획은 날짜만 키로 쓰므로
   333	    // 오늘치가 남아 있으면 스스로 갱신되지 않는다 — 클라가 재생성 CTA를 띄운다.
   334	    const ctx = gradeContext(to_type);
   335	    return NextResponse.json({
   336	      success: true,
   337	      from_type: fromType,
   338	      to_type,
   339	      kind: check.kind,
   340	      transition_id: transition?.id ?? null,
   341	      description: describeTransition(fromType, to_type, check.kind),
   342	      grade_context: {
   343	        label: ctx.fullLabel,
   344	        grade_system: ctx.gradeSystem,
   345	        exam_year: ctx.examYear,
   346	        show_suneung_dday: ctx.showSuneungDday,
   347	        suneung_dday: getSuneungDdayForStudentType(to_type),
   348	      },
   349	      grade_system_change: check.gradeSystem,
   350	      stamped_grade_rows: stampedGradeRows,
   351	      cleared_overrides: clearedOverrides,
   352	      plan_affecting: true,
   353	      daily_plan_stale: await isDailyPlanStale(studentId),
   354	    });
   355	  } catch (e) {
   356	    return authErrorResponse(e);
   357	  }
   358	}
