     2	// lib/promotion.ts
     3	// 학년(students.type) 변경 = 진급 이벤트의 순수 도메인 로직 (#208).
     4	//
     5	// type 변경은 단순 필드 수정이 아니다. 내신 등급제(5↔9)·수능 D-day 기준 학년도·
     6	// 교육과정(2022/2015)·계획 캐시 지문이 한꺼번에 따라 움직인다. 그래서 프로필
     7	// 편집 화이트리스트(lib/profile-patch.ts)에서 type을 빼고 이 전용 경로로 분리했다.
     8	//
     9	// 이 모듈은 순수하다 — supabaseAdmin 등 서버 전용 모듈을 임포트하지 않으므로
    10	// 유닛테스트(node env)에서 직접 임포트할 수 있다. 배선은 API 라우트가 한다.
    11	//
    12	// ⚠️ 알려진 한계(이 티켓 범위 밖, 후속 필요):
    13	//   gradeContext는 학년→대입학년도를 리터럴로 갖고 있어 2026년 달력에서만 맞다.
    14	//   실제 불변량은 학년이 아니라 코호트(대입 학년도)다 — 2026년 고2는 2027년에
    15	//   고3이 되어도 여전히 2028 대입·5등급제다. 그래서 "진급하면 등급제가 바뀐다"는
    16	//   현재 코드의 동작이지 입시 제도의 진실이 아니다. 이 모듈은 그 동작을 숨기지
    17	//   않고 gradeSystemChange()로 드러내 사용자에게 확인시킨다.
    18	// ══════════════════════════════════════════════════════════════
    19	import { z } from 'zod';
    20	import { gradeContext, GRADE_SYSTEM_LABEL, type StudentType, type GradeSystem } from '@/lib/grade-system';
    21	import { gradeSystemForType } from '@/lib/grade-provenance';
    22	
    23	export const STUDENT_TYPES = ['high1', 'high2', 'high3', 'nsu'] as const;
    24	
    25	/**
    26	 * 전환 종류.
    27	 *   promotion  — 정상 진급(고1→고2, 고2→고3)
    28	 *   retake     — 재수 전환(고3→N수)
    29	 *   correction — 재분류·오입력 정정(역방향 포함). 루틴 이벤트가 아니므로 사유 필수.
    30	 *   revert     — 직전 전환 되돌리기(오조작 복구)
    31	 */
    32	export type TransitionKind = 'promotion' | 'retake' | 'correction' | 'revert';
    33	
    34	/** 요청 스키마. student_id 생략 시 세션 학생 본인. */
    35	export const PromotionRequestSchema = z
    36	  .object({
    37	    student_id: z.string().uuid().optional(),
    38	    to_type: z.enum(STUDENT_TYPES),
    39	    reason: z.string().max(300).optional(),
    40	  })
    41	  .strict();
    42	
    43	export type PromotionRequest = z.infer<typeof PromotionRequestSchema>;
    44	
    45	const PROMOTION_STEPS: Partial<Record<StudentType, StudentType>> = {
    46	  high1: 'high2',
    47	  high2: 'high3',
    48	};
    49	
    50	/**
    51	 * 전환 종류 판정. `isRevertOfLatest`는 "이 전환이 가장 최근 전환을 정확히 되돌리는가"로,
    52	 * 호출자가 이력을 조회해 넘긴다(순수성 유지).
    53	 */
    54	export function classifyTransition(
    55	  from: StudentType,
    56	  to: StudentType,
    57	  isRevertOfLatest = false
    58	): TransitionKind {
    59	  if (isRevertOfLatest) return 'revert';
    60	  if (PROMOTION_STEPS[from] === to) return 'promotion';
    61	  if (from === 'high3' && to === 'nsu') return 'retake';
    62	  return 'correction';
    63	}
    64	
    65	/**
    66	 * 사유가 필수인가. 정상 진급·재수·되돌리기는 흐름상 자명하지만,
    67	 * 재분류(correction)는 왜 바꿨는지가 남지 않으면 나중에 판단할 수 없다.
    68	 */
    69	export function transitionRequiresReason(kind: TransitionKind): boolean {
    70	  return kind === 'correction';
    71	}
    72	
    73	/**
    74	 * 코호트 밴드(고1·2 = 2022 개정/5등급제 세대 ↔ 고3·N수 = 2015 개정/9등급제 세대)를 넘는가.
    75	 * 넘으면 학습 단계 어휘(student-classifier의 HIGH12_PHASE_OPTIONS ↔ PHASE_OPTIONS)와
    76	 * 교육과정 과목 풀(2022 ↔ 2015)이 통째로 달라진다.
    77	 */
    78	export function crossesCohortBand(from: StudentType, to: StudentType): boolean {
    79	  const band = (t: StudentType) => (t === 'high1' || t === 'high2' ? 'new2028' : 'current');
    80	  return band(from) !== band(to);
    81	}
    82	
    83	export interface GradeSystemChange {
    84	  from: GradeSystem;
    85	  to: GradeSystem;
    86	  changed: boolean;
    87	  /** 사용자에게 보여줄 경고 문구. 안 바뀌면 null. */
    88	  notice: string | null;
    89	}
    90	
    91	/**
    92	 * 이 전환이 내신 등급제를 바꾸는가 — 바꾼다면 사용자에게 반드시 알려야 한다.
    93	 *
    94	 * 과거 성적은 각인된 등급제(grades.grade_system)로 계속 해석되므로 위조되지 않지만,
    95	 * 앞으로 입력하는 내신의 등급 범위가 달라진다.
    96	 */
    97	export function gradeSystemChange(from: StudentType, to: StudentType): GradeSystemChange {
    98	  const fromSystem = gradeSystemForType(from);
    99	  const toSystem = gradeSystemForType(to);
   100	  const changed = fromSystem !== toSystem;
   101	  return {
   102	    from: fromSystem,
   103	    to: toSystem,
   104	    changed,
   105	    notice: changed
   106	      ? `내신 등급제가 ${GRADE_SYSTEM_LABEL[fromSystem]} → ${GRADE_SYSTEM_LABEL[toSystem]}로 바뀝니다. ` +
   107	        `이미 기록된 성적은 입력 당시 등급제로 계속 표시되며 환산하지 않습니다.`
   108	      : null,
   109	  };
   110	}
   111	
   112	/** 전환 한 줄 설명("고2 → 고3 진급"). 이력 UI·감사 로그 공용. */
   113	export function describeTransition(
   114	  from: StudentType,
   115	  to: StudentType,
   116	  kind: TransitionKind
   117	): string {
   118	  const label: Record<TransitionKind, string> = {
   119	    promotion: '진급',
   120	    retake: '재수 전환',
   121	    correction: '학년 정정',
   122	    revert: '되돌리기',
   123	  };
   124	  return `${gradeContext(from).gradeLabelShort} → ${gradeContext(to).gradeLabelShort} ${label[kind]}`;
   125	}
   126	
   127	export interface PromotionValidation {
   128	  ok: boolean;
   129	  /** ok=false일 때 사용자에게 보여줄 이유. */
   130	  error: string | null;
   131	  kind: TransitionKind;
   132	  gradeSystem: GradeSystemChange;
   133	  /** 코호트 밴드를 넘어 학습 단계 보정(profile_overrides.study_phase)을 비워야 하는가. */
   134	  clearsStudyPhaseOverride: boolean;
   135	}
   136	
   137	/**
   138	 * 전환 가능 여부 + 파생 정보. 라우트는 이 결과만 보고 분기한다.
   139	 *
   140	 * 되돌리기·재분류를 포함해 모든 방향을 허용한다 — 오입력 정정 수요가 실재하고
   141	 * (온보딩에서 학년을 잘못 고른 학생), 막아 두면 지원팀이 DB를 직접 만지게 된다.
   142	 * 대신 correction은 사유를 강제하고 전 이력을 남긴다.
   143	 */
   144	export function validatePromotion(args: {
   145	  from: StudentType;
   146	  to: StudentType;
   147	  reason?: string | null;
   148	  isRevertOfLatest?: boolean;
   149	}): PromotionValidation {
   150	  const { from, to, reason, isRevertOfLatest = false } = args;
   151	  const kind = classifyTransition(from, to, isRevertOfLatest);
   152	  const gradeSystem = gradeSystemChange(from, to);
   153	  const clearsStudyPhaseOverride = crossesCohortBand(from, to);
   154	
   155	  if (from === to) {
   156	    return {
   157	      ok: false,
   158	      error: '이미 같은 학년입니다.',
   159	      kind,
   160	      gradeSystem,
   161	      clearsStudyPhaseOverride,
   162	    };
   163	  }
   164	  if (transitionRequiresReason(kind) && !reason?.trim()) {
   165	    return {
   166	      ok: false,
   167	      error: '학년 정정은 사유를 입력해야 합니다.',
   168	      kind,
   169	      gradeSystem,
   170	      clearsStudyPhaseOverride,
   171	    };
   172	  }
   173	  return { ok: true, error: null, kind, gradeSystem, clearsStudyPhaseOverride };
   174	}
