+/**
+ * 미각인 성적 행에 "현재 학년 기준" 등급제를 각인한다. type을 바꾸기 직전에만 호출.
+ * 이 시점의 students.type이 곧 그 성적들이 기록될 때의 type이므로 추정이 아니라 사실이다.
+ * (p143 백필과 같은 규칙 — mock·suneung은 학년 무관 g9, 내신·미지정은 학년 기준.)
+ *
+ * ── 원자성 없음. 대신 실패 방향이 안전하도록 순서를 고정한다 ──
+ * Supabase REST는 문 단위 autocommit이라 "각인 + type 변경"을 한 트랜잭션으로 묶지
+ * 못한다. 그래서 **순서가 안전장치다**: 반드시 각인이 먼저, type 변경이 나중.
+ *
+ *   · 각인 일부/전부 성공 → type 변경 실패:  무해하다. 각인값은 여전히 정확하고
+ *     (type이 안 바뀌었으므로), 재시도하면 남은 NULL을 같은 값으로 마저 채운다.
+ *     각인은 NULL만 채우는 멱등 연산이라 중복 실행이 값을 바꾸지 않는다.
+ *   · 각인 실패 → 호출부가 type을 바꾸지 않고 500으로 중단한다(아래 ① 참고).
+ *   · **반대 순서(type 먼저)였다면 영구 위조다** — type이 바뀐 뒤엔 그 성적들이
+ *     원래 몇 등급제였는지 어디에도 남아 있지 않아 복원할 방법이 없다.
+ *
+ * 각인과 type 변경 사이에 들어온 성적 쓰기도 안전하다 — 세 쓰기 경로가 저장 시점에
+ * 스스로 stampGradeSystem으로 각인하므로 이 구간에서 NULL 행이 새로 생기지 않는다.
+ *
+ * 이 순서 계약은 tests/promotion-order-contract.test.ts가 소스 수준에서 잠근다.
+ */
+async function stampUnstampedGrades(studentId: string, currentType: StudentType): Promise<number> {
+  // 1) 모의고사·수능 → 항상 g9
+  const { data: mockRows, error: mockErr } = await supabaseAdmin
+    .from('grades')
+    .update({ grade_system: stampGradeSystem('mock', currentType) })
+    .eq('student_id', studentId)
+    .is('grade_system', null)
+    .in('report_type', ['mock', 'suneung'])
+    .select('id');
+  if (mockErr) throw mockErr;
+
+  // 2) 남은 행(내신 + report_type 미지정) → 현재 학년 기준
+  const { data: naesinRows, error: naesinErr } = await supabaseAdmin
+    .from('grades')
+    .update({ grade_system: stampGradeSystem('naesin', currentType) })
+    .eq('student_id', studentId)
+    .is('grade_system', null)
+    .select('id');
+  if (naesinErr) throw naesinErr;
+
+  return (mockRows?.length ?? 0) + (naesinRows?.length ?? 0);
+}
+
+/** 오늘 일간 계획이 옛 학년 기준으로 캐시돼 있는가. */
+async function isDailyPlanStale(studentId: string): Promise<boolean> {
+  const { data } = await supabaseAdmin
+    .from('study_plans')
+    .select('content_json')
+    .eq('student_id', studentId)
+    .eq('plan_type', 'daily')
+    .order('created_at', { ascending: false })
+    .limit(1)
+    .maybeSingle();
+  const cachedDate = (data?.content_json as { date?: string } | null)?.date;
+  return cachedDate === todayKST();
+}
