 async function findStudent(userId: string): Promise<{ id: string; type: StudentType }> {
   const { data, error } = await supabaseAdmin
     .from('students')
     .select('id, type')
     .eq('user_id', userId)
     .maybeSingle();
   if (error || !data) throw new AuthError(404, '학생 프로필이 없습니다');
   return { id: data.id, type: data.type as StudentType };
 }

 // GET 페이징(limit·offset)은 lib/grades-paging.ts의 순수 함수로 파싱한다.
