     const { limit, offset } = parseGradesPaging(new URL(req.url).searchParams);

     // exam_date 동률 시 id로 2차 정렬 — offset 페이징이 페이지 경계에서
     // 흔들리지 않도록(누락·중복 방지) 결정적 순서를 고정한다.
     const { data, count, error } = await supabaseAdmin
       .from('grades')
       .select(
-        'id, exam_name, subject, grade, raw_score, percentile, standard_score, achievement, converted_score, rank, rank_total, report_type, subject_average, std_dev, grade_level, semester, exam_date',
