         { count: 'exact' }
       )
       .eq('student_id', studentId)
       .order('exam_date', { ascending: false })
       .order('id', { ascending: false })
       .range(offset, offset + limit - 1);
     if (error) throw new AuthError(500, '조회 실패');

     return NextResponse.json({
