     9	export interface RateResult {
    10	  ok: boolean;
    11	  retryAfterSec: number;
    12	}
    13	
    14	export function rateLimit(key: string, limit: number, windowMs: number): RateResult {
    15	  const now = Date.now();
    16	  const arr = (hits.get(key) ?? []).filter((t) => now - t < windowMs);
    17	  if (arr.length >= limit) {
    18	    hits.set(key, arr);
    19	    const oldest = arr[0];
    20	    const retryAfterSec = Math.max(1, Math.ceil((windowMs - (now - oldest)) / 1000));
    21	    return { ok: false, retryAfterSec };
    22	  }
    23	  arr.push(now);
    24	  hits.set(key, arr);
    25	  // 메모리 누수 방지 — 맵이 너무 커지면 오래된 키 정리
    26	  if (hits.size > 5000) {
    27	    for (const [k, v] of hits) {
    28	      if (v.every((t) => now - t > windowMs)) hits.delete(k);
    29	    }
    30	  }
    31	  return { ok: true, retryAfterSec: 0 };
    32	}

