     2	// lib/profile-patch.ts
     3	// 프로필 편집(EP-24, GH#194)의 순수 검증 로직 — Zod 화이트리스트 +
     4	// plan-affecting 판정. supabaseAdmin 등 서버 전용 모듈을 임포트하지 않으므로
     5	// 유닛테스트(tests/profile-patch-schema.test.ts, node env)에서 직접 임포트할 수
     6	// 있다. (라우트 모듈을 임포트하면 lib/supabase.ts가 import 시점에 env를 검증하다
     7	// 던져 테스트가 안 뜬다 — 그래서 순수 로직을 여기로 분리.)
     8	//
     9	// 화이트리스트(확정 #194): 목표대학·선택과목(수능/고교학점제)·스타일·
    10	//   인강교재 성향·집중시간·진로 관심 배열 + exam_type. 학년(type)은 제외 — 진급 이벤트라
    11	//   별도 티켓 #208. 소감(subject_feedback)은 EP-23/p61 착지 후 fast-follow.
    12	// ══════════════════════════════════════════════════════════════
    13	import { z } from 'zod';
    14	
    15	// ⚠️ .partial().strict() — 모든 필드 optional(전달된 필드만 부분 수정),
    16	//    화이트리스트 밖 키(type=학년 등)는 파싱 단계에서 거부. 이게 "학년 제외"를
    17	//    기계적으로 보장한다.
    18	export const ProfilePatchSchema = z
    19	  .object({
    20	    target_university: z.string().max(100),
    21	    goal_university_custom: z.string().max(100).nullable(),
    22	    exam_type: z.enum(['suneung', 'naesin', 'both']),
    23	    kor_subject: z.string().max(50).nullable(),
    24	    math_subject: z.string().max(50).nullable(),
    25	    science_subject_1: z.string().max(50).nullable(),
    26	    science_subject_2: z.string().max(50).nullable(),
    27	    // 세 버킷 모두 required — .default([])로 두면 부분 객체({general:[...]})가 나머지
    28	    // 버킷을 조용히 빈 배열로 덮어써(무음 삭제) 직접 API 호출 시 데이터가 사라진다.
    29	    // 편집면은 항상 세 버킷을 다 보내므로 required가 안전하고, 각 배열 .max(50)로 JSONB 비대화 방지.
    30	    selected_subjects: z.object({
    31	      general: z.array(z.string().max(50)).max(50),
    32	      career: z.array(z.string().max(50)).max(50),
    33	      fusion: z.array(z.string().max(50)).max(50),
    34	    }),
    35	    study_styles: z.array(z.enum(['concept', 'problem'])).min(1).max(2),
    36	    // EP-21(p60) 이후 매체 선호의 정본은 medium_pref_ratio(0~100 슬라이더).
    37	    // legacy medium_pref(enum)를 여기서 받으면 resolveMediumRatio가 ratio 우선이라
    38	    // 편집이 계획에 영영 반영되지 않는다(Codex 웨이브 리뷰 P1) — ratio만 허용.
    39	    medium_pref_ratio: z.number().int().min(0).max(100),
    40	    focus_minutes: z.number().int().min(20).max(120),
    41	    career_interests: z.array(z.string().max(30)).max(10),
    42	    // legacy 단일 텍스트 호출도 받아 route에서 career_interests 정본으로 동기화한다.
    43	    career_interest: z.string().max(100).nullable(),
    44	  })
    45	  .partial() // 모든 필드 optional — 전달된 필드만 부분 수정.
    46	  .strict();
    47	
    48	export type ProfilePatch = z.infer<typeof ProfilePatchSchema>;
    49	
    50	// 계획 캐시 지문(generate-plan buildInputFingerprint)에 포함된 필드 —
    51	// 바꾸면 다음 생성 때 캐시가 자동 무효화된다 → "다음 생성에 반영" 배너 트리거.
    52	// selected_subjects·goal_university_custom은 지문 밖(계획에 아직 안 쓰임) →
    53	// 편집은 허용하되 배너는 안 띄운다(정직).
    54	const PLAN_AFFECTING_KEYS = new Set<keyof ProfilePatch>([
    55	  'target_university',
    56	  'exam_type',
    57	  'kor_subject',
    58	  'math_subject',
    59	  'science_subject_1',
    60	  'science_subject_2',
    61	  'study_styles',
    62	  'medium_pref_ratio',
    63	  'focus_minutes',
    64	  'career_interests',
    65	  'career_interest',
    66	]);
    67	
    68	/** 이번 요청이 계획 캐시 지문에 영향을 주는 필드를 하나라도 건드렸는가. */
    69	export function isPlanAffecting(keys: string[]): boolean {
    70	  return keys.some((k) => PLAN_AFFECTING_KEYS.has(k as keyof ProfilePatch));
    71	}
    72	
    73	/**
    74	 * 설정 화면은 진로를 한 줄 텍스트로 편집한다. 저장 시 p60 정본(career_interests 배열)으로
    75	 * 함께 동기화해야 generate-plan/선택과목 추천 소비단이 실제 변경값을 읽는다.
    76	 */
    77	export function careerInterestTextToInterests(value: string | null | undefined): string[] {
    78	  const raw = value?.trim();
    79	  if (!raw) return [];
    80	  const seen = new Set<string>();
    81	  const interests: string[] = [];
    82	  for (const part of raw.split(',')) {
    83	    const item = part.trim().slice(0, 30);
    84	    if (!item || seen.has(item)) continue;
    85	    seen.add(item);
    86	    interests.push(item);
    87	    if (interests.length >= 10) break;
    88	  }
    89	  return interests;
    90	}

