    18	// ══════════════════════════════════════════════════════════════
    19	import { NextRequest, NextResponse } from 'next/server';
    20	import { supabaseAdmin } from '@/lib/supabase';
    21	import { requireUser, getUserRole, AuthError, authErrorResponse } from '@/lib/auth';
    22	import { ProfilePatchSchema, careerInterestTextToInterests, isPlanAffecting } from '@/lib/profile-patch';
