    28	
    29	export async function PATCH(req: NextRequest): Promise<NextResponse> {
    30	  try {
    31	    const user = await requireUser();
    32	
    33	    const role = await getUserRole(user.id);
    34	    if (role !== 'student') {
    35	      throw new AuthError(403, '학생 계정만 프로필을 편집할 수 있습니다.');
    36	    }
    37	
    38	    const { data: student, error: sErr } = await supabaseAdmin
    39	      .from('students')
    40	      .select('id')
    41	      .eq('user_id', user.id)
    42	      .maybeSingle();
    43	    if (sErr || !student) {
    44	      throw new AuthError(404, '학생 프로필이 없습니다.');
    45	    }
    46	
    47	    const body = await req.json();
    48	    const parsed = ProfilePatchSchema.safeParse(body);
    49	    if (!parsed.success) {
    50	      return NextResponse.json(
    51	        { error: '입력 데이터 오류', details: parsed.error.flatten() },
    52	        { status: 400 }
    53	      );
    54	    }
    55	    const data = parsed.data;
    56	    const providedKeys = Object.keys(data);
    57	    if (providedKeys.length === 0) {
    58	      return NextResponse.json({ error: '수정할 항목이 없습니다.' }, { status: 400 });
    59	    }
    60	
    61	    // ── students 테이블 업데이트 ──
    62	    // 빈 문자열('선택 안 함')은 null로 정규화(다른 문자열 필드와 정합 — goalUniversityLabel·
    63	    // 지문·매칭 점수가 빈 문자열을 코드로 오인하지 않게).
    64	    const studentPatch: Record<string, unknown> = {};
    65	    if ('target_university' in data) studentPatch.target_university = data.target_university || null;
    66	    if ('goal_university_custom' in data) studentPatch.goal_university_custom = data.goal_university_custom;
    67	    if ('exam_type' in data) studentPatch.exam_type = data.exam_type;
    68	    if (Object.keys(studentPatch).length > 0) {
    69	      const { error } = await supabaseAdmin
    70	        .from('students')
    71	        .update(studentPatch)
    72	        .eq('id', student.id);
    73	      if (error) {
    74	        console.error('[profile PATCH] students update error:', error);
    75	        return NextResponse.json({ error: '학생 정보 저장 실패' }, { status: 500 });
    76	      }
    77	    }
    78	
    79	    // ── student_profiles 테이블 업데이트(upsert — 온보딩 미완 행 대비) ──
    80	    const profilePatch: Record<string, unknown> = {};
    81	    if ('kor_subject' in data) profilePatch.kor_subject = data.kor_subject;
    82	    if ('math_subject' in data) profilePatch.math_subject = data.math_subject;
    83	    if ('science_subject_1' in data) profilePatch.science_subject_1 = data.science_subject_1;
    84	    if ('science_subject_2' in data) profilePatch.science_subject_2 = data.science_subject_2;
    85	    if ('selected_subjects' in data) profilePatch.selected_subjects = data.selected_subjects;
    86	    if ('medium_pref_ratio' in data) profilePatch.medium_pref_ratio = data.medium_pref_ratio;
    87	    if ('focus_minutes' in data) profilePatch.focus_minutes = data.focus_minutes;
    88	    if ('career_interest' in data) {
    89	      const careerInterest = data.career_interest?.trim() || null;
    90	      profilePatch.career_interest = careerInterest;
    91	      profilePatch.career_interests = careerInterestTextToInterests(careerInterest);
    92	    }
    93	    if ('career_interests' in data) {
    94	      const careerInterests = data.career_interests ?? [];
    95	      profilePatch.career_interests = careerInterests;
    96	      // p60 이후 정본은 career_interests 배열. legacy 단일 컬럼은 첫 값으로 동기화해
    97	      // p60 이전 소비단·리포트 폴백이 같은 값을 보게 한다.
    98	      profilePatch.career_interest = careerInterests[0] ?? null;
    99	    }
   100	    // 목표대학은 students·student_profiles 양쪽에 동기 저장(온보딩 대칭). ''→null 정규화.
   101	    if ('target_university' in data) profilePatch.goal_university = data.target_university || null;
   102	    // 스타일: study_styles(배열=정본) + study_style(레거시 스칼라) 동기화.
   103	    //   온보딩과 동일 규칙 — 1개면 그 값, 2개면 'mixed'. 중복 제거 후 판정
   104	    //   (['concept','concept']를 'mixed'로 오판정하지 않게).
   105	    if ('study_styles' in data && data.study_styles) {
   106	      const uniqueStyles = Array.from(new Set(data.study_styles));
   107	      profilePatch.study_styles = uniqueStyles;
